def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0

    # Initialize arrays to store the lengths of increasing and decreasing subsequences
    left_increasing = [1] * n
    right_decreasing = [1] * n

    # Calculate the length of the longest increasing subsequence ending at each position
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1

    # Calculate the length of the longest decreasing subsequence starting at each position
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_decreasing[i] = right_decreasing[i + 1] + 1

    # Find the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, left_increasing[i] + right_decreasing[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

